import React, { useState } from "react";
import "../styles/Funds.css";
import Home from "../pages/Home";

const quickAmounts = [100, 250, 500, 1000, 2500, 5000];

function Funds() {
  const [amount, setAmount] = useState("");
  const [loading, setLoading] = useState(false);

  const currencySymbol = "₹";

  const handleAmount = (value) => {
    setAmount(value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const numericAmount = Number(amount);

    if (!numericAmount || numericAmount < 10) {
      alert("Minimum amount is ₹10.");
      return;
    }

    if (numericAmount > 100000) {
      alert("Maximum amount is ₹100,000.");
      return;
    }

    try {
      setLoading(true);

      const token = localStorage.getItem("token");

      if (!token) {
        alert("Please login again.");
        return;
      }

      // 1. Create Razorpay order
      const response = await fetch(
        "http://localhost:5000/api/payments/create",
        {
          method: "POST",

          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },

          body: JSON.stringify({
            amount: numericAmount,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok || !data.success) {
        throw new Error(
          data.message || "Unable to create payment."
        );
      }

      // 2. Make sure Razorpay Checkout is loaded
      if (!window.Razorpay) {
        throw new Error(
          "Razorpay Checkout is not loaded."
        );
      }

      // 3. Razorpay Checkout options
      const options = {
        key: data.razorpay.keyId,

        amount: data.razorpay.amount,

        currency: data.razorpay.currency,

        name: "RGBHAI SMM Panel",

        description: "Wallet Add Funds",

        order_id: data.razorpay.orderId,

        // We will implement verification here later.
        handler: function (paymentResponse) {
          console.log(
            "Razorpay payment response:",
            paymentResponse
          );

          alert(
            "Payment completed. Verification is pending."
          );
        },

        theme: {
          color: "#2563eb",
        },

        modal: {
          ondismiss: function () {
            console.log(
              "Razorpay checkout closed"
            );
          },
        },
      };

      // 4. Open Razorpay
      const razorpay = new window.Razorpay(
        options
      );

      razorpay.on(
        "payment.failed",
        function (response) {
          console.error(
            "Payment failed:",
            response.error
          );

          alert(
            response.error?.description ||
              "Payment failed."
          );
        }
      );

      razorpay.open();

    } catch (error) {
      console.error(
        "Add funds error:",
        error
      );

      alert(
        error.message ||
          "Unable to start payment."
      );

    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="funds-page">

      <Home />

      <main className="funds-container">

        {/* ================= HEADER ================= */}

        <div className="funds-heading">

          <h1>
            Add Funds
          </h1>

          <p>
            Add money to your account securely
            using UPI QR Code.
          </p>

        </div>

        {/* ================= LAYOUT ================= */}

        <div className="funds-layout">

          {/* ================= PAYMENT CARD ================= */}

          <div className="payment-card">

            <div className="payment-card-heading">

              <div className="wallet-icon">
                ₹
              </div>

              <div>
                <h2>
                  Add Balance
                </h2>

                <p>
                  Enter the amount you want
                  to add.
                </p>
              </div>

            </div>

            <form onSubmit={handleSubmit}>

              {/* Currency */}

              <div className="fund-form-group">

                <label>
                  Currency
                </label>

                <select
                  value="INR"
                  disabled
                >
                  <option value="INR">
                    INR - Indian Rupee ₹
                  </option>
                </select>

              </div>

              {/* Amount */}

              <div className="fund-form-group">

                <label>
                  Amount
                </label>

                <div className="amount-input">

                  <span>
                    ₹
                  </span>

                  <input
                    type="number"
                    value={amount}
                    onChange={(e) =>
                      handleAmount(
                        e.target.value
                      )
                    }
                    placeholder="Enter amount"
                    min="10"
                    max="100000"
                    step="1"
                  />

                </div>

              </div>

              {/* Quick Amounts */}

              <div className="quick-amounts">

                <label>
                  Quick Select
                </label>

                <div className="quick-buttons">

                  {quickAmounts.map(
                    (quickAmount) => (
                      <button
                        type="button"
                        key={quickAmount}
                        onClick={() =>
                          handleAmount(
                            quickAmount
                          )
                        }
                        className={
                          Number(amount) ===
                          quickAmount
                            ? "quick-btn selected"
                            : "quick-btn"
                        }
                      >
                        ₹{quickAmount}
                      </button>
                    )
                  )}

                </div>

              </div>

              {/* ================= QR PAYMENT ================= */}

              <div className="payment-section">

                <label className="payment-label">
                  Payment Method
                </label>

                <div className="payment-methods">

                  <div className="payment-method selected">

                    <div className="method-icon">
                      ▦
                    </div>

                    <div className="method-content">

                      <strong>
                        UPI QR Code
                      </strong>

                      <span>
                        Scan and pay using
                        any supported UPI app.
                      </span>

                    </div>

                    <div className="method-radio">
                      ✓
                    </div>

                  </div>

                </div>

              </div>

              {/* Payment Notice */}

              <div className="payment-notice">

                <div className="notice-icon">
                  i
                </div>

                <p>
                  Your payment is processed
                  securely through Razorpay.
                  Do not close the payment
                  window until the transaction
                  is completed.
                </p>

              </div>

              {/* Submit */}

              <button
                type="submit"
                className="add-money-button"
                disabled={loading}
              >

                {loading
                  ? "Creating Payment..."
                  : "Continue to Payment"}

                <span>
                  →
                </span>

              </button>

            </form>

          </div>

          {/* ================= SIDEBAR ================= */}

          <aside className="funds-sidebar">

            {/* Current Balance */}

            <div className="current-balance-card">

              <div className="balance-card-top">

                <div>

                  <span>
                    Current Balance
                  </span>

                  <strong>
                    ₹0.00
                  </strong>

                </div>

                <div className="big-wallet">
                  ₹
                </div>

              </div>

              <div className="balance-line" />

              <p>
                Your available balance can
                be used to place new orders.
              </p>

            </div>

            {/* Payment Summary */}

            <div className="fund-summary-card">

              <h3>
                Payment Summary
              </h3>

              <div className="fund-summary-row">

                <span>
                  Amount
                </span>

                <strong>
                  {amount
                    ? `₹${Number(
                        amount
                      ).toFixed(2)}`
                    : "₹0.00"}
                </strong>

              </div>

              <div className="fund-summary-row">

                <span>
                  Payment Method
                </span>

                <strong>
                  UPI QR
                </strong>

              </div>

              <div className="fund-summary-row">

                <span>
                  Processing Fee
                </span>

                <strong className="green">
                  Free
                </strong>

              </div>

              <div className="summary-separator" />

              <div className="fund-total">

                <span>
                  Total
                </span>

                <strong>
                  {amount
                    ? `₹${Number(
                        amount
                      ).toFixed(2)}`
                    : "₹0.00"}
                </strong>

              </div>

            </div>

            {/* Help */}

            <div className="fund-help-card">

              <div className="help-title">

                <div className="help-question">
                  ?
                </div>

                <h3>
                  Need Help?
                </h3>

              </div>

              <p>
                Having trouble adding funds?
                Contact our support team.
              </p>

              <a href="/support">
                Contact Support →
              </a>

            </div>

          </aside>

        </div>

      </main>

    </div>
  );
}

export default Funds;
